agraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.33,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="54.53" /><TableColumn Width="269.87" /><TableColumn Width="269.87" /><TableColumn Width="269.73" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.53,4.13,0.33" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.33,0"><Span FontWeight="Bold" Foreground="#FFFFFFFF"><Run>CIP-006-5 Table R1 - Physical Security Plan</Run></Span><Span><Run> </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.53,4.13,0.33" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.53,4.13,0.33" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.73,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.53,4.13,0.33" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.73,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.53,4.13,0.33" BorderThickness="1,1,1,1" Bo