hat includes each of the applicable requirement parts in CIP-004-6 Table R2-- Cyber Security Training Program and additional evidence to demonstrate implementation of the program(s).</Run></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="85.4" /><TableColumn Width="256.53" /><TableColumn Width="262.2" /><TableColumn Width="259.8" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.27,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R2-- </Run><Span FontFamily="Calibri"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Cyber Security Training Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.27,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.27,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground