gin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.13,3.4" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Process to confirm identity. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.13,3.4" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of the Responsible </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run>Entity’s process to confirm identity. </Run></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="37.4,0,0.67,10.67"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,959.6,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="43.07" /><TableColumn Width="274.73" /><TableColumn Width="274.6" /><TableColumn Width="274.6" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R3-- </Run><Span FontFamily="Calibri"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Personnel Risk Assessment Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.47,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems</Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>3.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,2.6,1"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,8"><Span><Run>Process to perform a seven year criminal history records check as part of each personnel risk assessment that includes:  </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="12.27,0,0,8"><Span><Run>3.2.1. current residence, regardless of duration; and  </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="12.27,0,0,8"><Span><Run>3.2.2. other locations where, during the seven years immediately prior to the date of the criminal history records check, the subject has resided for six consecutive months or more. </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>If it is not possible to perform a full seven year criminal history records check, conduct as much of the seven year criminal history records check as possible and document the reason the full seven year criminal history records check could not be performed. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run>An example of evidence may include, but is not limited to, documentation of the Responsible Entity’s process to perform a seven year criminal history records check.  </Run></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,959.6,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="43.33" /><TableColumn Width="295.6" /><TableColumn Width="295.53" /><TableColumn Width="237.47" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R3-- </Run><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Personnel Risk Assessment Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems</Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.87,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>3.3 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Criteria or process to evaluate criminal history records checks for authorizing access.  </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of the </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run>Responsible Entity’s process to evaluate criminal history records checks. </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>3.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.93"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Criteria or process for verifying that personnel risk assessments performed for contractors or service vendors are conducted according to Parts 3.1 through 3.3</Run></Span><Span FontFamily="Times New Roman" FontStyle="Italic"><Run>.</Run></Span><Span><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.2,3.53" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of the </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run>Responsible Entity’s criteria or process for verifying contractors or service vendors personnel risk assessments. </Run></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,959.6,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="43.33" /><TableColumn Width="295.6" /><TableColumn Width="295.53" /><TableColumn Width="237.47" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.2,3.4" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment=