dding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph TextAlignment="Justify" FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,10.07"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="43.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,35.27"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,10.67"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="43.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Utilize an Intermediate System such that the Cyber Asset initiating Interactive Remote Access does not directly access an applicable Cyber Asset. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, network diagrams or architecture documents. </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph TextAlignment="Justify" FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,10.07"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="43.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,35.27"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,10.07"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="43.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri"><Run>For all Interactive Remote Access sessions, utilize encryption that terminates at an Intermediate System.</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>A