t MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Mitigate the threat of detected malicious code. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>Examples of evidence may include, but are not limited to: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="33.47,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,9.8"><Span><Run>Records of response processes for malicious code detection</Run></Span></Paragraph></ListItem><ListItem Margin="33.47,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>Records of the performance of these processes when malicious code is detected.</Run></Span></Paragraph></ListItem></List></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>3.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,36.93"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.87"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri"><Run>For those methods identified in Part 3.1 that use signatures or patterns, have a process for the update of the signatures or patterns. The process must address testing and installing the signatures or patterns.</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation showing the process used for the update of signatures or patterns. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Malicious Code Prevention', 0, NULL, N'NERC_CIP_R6', NULL, NULL, 8549, 25, NULL, NULL)
<Section xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xml:space="preserve" TextAlignment="Left" LineHeight="Auto" IsHyphenationEnabled="False" xml:lang="en-us" FlowDirection="LeftToRight" NumberSubstitution.CultureSource="Text" NumberSubstitution.Substitution="AsCulture" FontFamily="Segoe UI" FontStyle="Normal" FontWeight="Normal" FontStretch="Normal" FontSize="12" Foreground="#FF000000" Typography.StandardLigatures="True" Typography.ContextualLigatures="True" Typography.DiscretionaryLigatures="False" Typography.HistoricalLigatures="False" Typography.AnnotationAlternates="0" Typography.ContextualAlternates="True" Typography.HistoricalForms="False" Typography.Kerning="True" Typography.CapitalSpacing="False" Typography.CaseSensitiveForms="False" Typography.StylisticSet1="False" Typography.StylisticSet2="False" Typography.StylisticSet3="False" Typography.StylisticSet4="False" Typography.StylisticSet5="False" Typography.StylisticSet6="False" Typography.StylisticSet7="False" Typography.StylisticSet8="False" Typography.StylisticSet9="False" Typography.StylisticSet10="False" Typography.StylisticSet11="False" Typography.StylisticSet12="False" Typography.StylisticSet13="False" Typography.StylisticSet14="False" Typography.StylisticSet15="False" Typography.StylisticSet16="False" Typography.StylisticSet17="False" Typography.StylisticSet18="False" Typography.StylisticSet19="False" Typography.StylisticSet20="False" Typography.Fraction="Normal" Typography.SlashedZero="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,10.67"><Run FontFamily="Georgia" FontSize="16">M4. Evidence must include each of the documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table R4-- Security Event Monitoring and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="66.67" /><TableColumn Width="262.67" /><TableColumn Width="266.73" /><TableColumn Width="267.87" /></Table.Columns><TableRowGroup><TableRow><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,0,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph></TableCell><TableCell ColumnSpan="2" Padding="7.13,7.47,4.07,0" BorderThickness="0,1,0,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Right" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.67,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R4-- Security Event Monitoring </Run></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="0,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>4.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,10.33"><Span><Run>Log events at the BES Cyber System level (per BES Cyber System capability) or at the Cyber Asset level (per Cyber Asset capability) for identification of, and after-the-fact investigations of, Cyber Security Incidents that includes, as a minimum, each of the following types of events:  </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="46.87,0,0,2.4"><Span><Run>4.1.1.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Detected successful login attempts; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="46.87,0,1.07,2.47"><Span><Run>4.1.2.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Detected failed access attempts and failed login attempts; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="4.87,0,0,0"><Span><Run>4.1.3.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Detected malicious code. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,2.4,0"><Span><Run>Examples of evidence may include, but are not limited to, a paper or system generated listing of event types for which the BES Cyber System is capable of detecting and, for generated events, is configured to log. This listing must include the required types of events.   </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="66.67" /><TableColumn Width="262.67" /><TableColumn Width="266.73" /><TableColumn Width="267.87" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R4-- Security Event Monitoring </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.53,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>4.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Generate alerts for security events that the Responsible Entity </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,10.33"><Span><Run>determines necessitates an alert, that includes, as a minimum, each of the following types of events (per Cyber Asset or BES Cyber System capability): </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="47.2,0,0,2.33"><Span><Run>4.2.1.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Detected malicious code from Part 4.1; and </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="47.2,0,0,0"><Span><Run>4.2.2.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Detected failure of Part 4.1 event logging. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0.53,0"><Span><Run>Examples of evidence may include, but are not limited to, paper or systemgenerated listing of security events that the Responsible Entity determined necessitate alerts, including paper or system generated list showing how alerts are configured. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="66.67" /><TableColumn Width="262.67" /><TableColumn Width="266.73" /><TableColumn Width="267.87" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R4-- Security Event Monitoring </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.53,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>4.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,31.87"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.87"><Span><Run>Medium Impact BES Cyber Systems at Control Centers and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Where technically feasible, retain applicable event logs identified in Part 4.1 for at least the last 90 consecutive calendar days except under CIP Exceptional Circumstances. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri"><Run>Examples of evidence may include, but are not limited to, documentation of the event log retention process and paper or system generated reports showing log retention configuration set at 90 days or greater.</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>4.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Review a summarization or sampling of logged events as determined by the Responsible Entity at intervals no greater than 15 calendar days to identify undetected Cyber Security Incidents.   </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, documentation describing the review, any findings from the review (if any), and dated documentation showing the review occurred. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Security Event Monitoring', 0, NULL, N'NERC_CIP_R6', NULL, NULL, 8550, 50, NULL, NULL)
