ro="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,10.67"><Run FontFamily="Georgia" FontSize="16">M5. Evidence must include each of the applicable documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table 5-- System Access Controls and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,10.67"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="51.13" /><TableColumn Width="260.8" /><TableColumn Width="288.8" /><TableColumn Width="263.2" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.2,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R5-- System Access Control </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.2,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="4.53,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></P