</List></TableCell><TableCell Padding="7.13,7.47,6.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Identify and inventory all known enabled default or other generic account types, either by system, by groups of systems, by location, or by system type(s). </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,6.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.13,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, a listing of accounts by account types showing the enabled or generic account types in use for the BES Cyber System.  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="51.73" /><TableColumn Width="263.73" /><TableColumn Width="290.07" /><TableColumn Width="268.47" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="4.73,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="2.87,0,0,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R5-- System Access Control </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="4.73,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="7.27,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="4.73,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Cente