.Columns><TableColumn Width="71.47" /><TableColumn Width="263.07" /><TableColumn Width="264.53" /><TableColumn Width="264.93" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.47,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-008-5 Table R1-- Cyber Security Incident Response Plan Specifications </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.27,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>1.3 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,6.4"><Span><Run>High Impact BES Cyber Systems </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Medium Impact BES Cyber Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>The roles and responsibilities of Cyber Security Incident response groups or individuals. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, dated Cyber Security Incident response process(es) or procedure(s) that define roles and responsibilities (e.g., monitoring, reporting, initiating, documenting, etc.) of Cyber Security Incident response groups or individuals.  </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>1.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,6.4"><Span><Run>High Impact BES Cyber Systems </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Medium Impact BES Cyber Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph TextAlignment="Justify" FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Incident handling procedures for Cyber Security Incidents. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,10.53,5,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, dated Cyber Security Incident response process(es) or procedure(s) that address incident handling (e.g., containment, eradication, recovery/incident resolution). </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'Incident Reporting and Response Planning', N'Cyber Security Incident Response Plan Specifications', 0, NULL, N'NERC_CIP_R6', NULL, NULL, 8565, 17, NULL, NULL)
