aph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,3.6,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,3.6,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,3.6,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.87"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,3.6,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Monitor at least once every 35 calendar days for changes to the baseline configuration (as described in </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Requirement R1, Part 1.1). Document and investigate detected unauthorized changes.   </Run></Span></Paragraph></Tabl