FF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.33,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,7.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1.07"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,7.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.07"><Span><Run>Prior to the release for reuse of applicable Cyber Assets that contain </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run>BES Cyber System Information (except for reuse within other systems identified in the Applicable Systems</Run><Span><Run> column), the Responsible Entity shall take action to prevent the unauthorized retrieval of BES Cyber System Information from the Cyber Asset data storage media.   </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.13,0,0,2"><Span><Run>Examples of acceptable evidence  include, but are not limited to:  </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="24.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,2.73,9.87"><Span><Run>Records tracking sanitization actions taken to prevent unauthorized retrieval of BES Cyber System Information such as clearing, purging, or destroying; or</Run></Span></Paragraph></ListItem><ListItem Margin="24.13,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,2.73,0"><Span><Run>Records tracking actions such as encrypting, retaining in the Physical Security Perimeter or other methods used to prevent unauthorized retrieval of BES Cyber System Information.</Run></Span></Paragraph></ListItem></List></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="1