stItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,31.93"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.8,0,0.4,0"><Span><Run>Require completion of the training specified in Part 2.1 at least once every 15 calendar months. </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="1.8,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, dated individual training records. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'Personnel & Training', N'Cyber Security Training Program', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8492, 51, NULL, 27168)
