1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,5.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R2--</Run><Span FontFamily="Calibri"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Cyber Security Training Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,4.53,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,4.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,5.93,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,5.87,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.73,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0.87"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0.93"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.8,0,0,0"><Span><Run>Require completion of the training specified in Part 2.1 prior to granting authorized electronic access and authorized unescorted physical access to applicable Cyber Assets, except during CIP Exceptional Circumstances.  </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="1.8,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, training records and documentation of when CIP Exceptional Circumstances were invoked. </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.73,0,0,0"><Span><Run>2.3 </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0.87"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,31.93"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.8,0,0.4,0"><Span><Run>Require completion of the training specified in Part 2.1 at least once every 15 calendar months. </Run></Span></Paragraph></TableCell><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="1.8,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, dated individual training records. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'Personnel & Training', N'Cyber Security Training Program', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8493, 51, NULL, 27169)
