leCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>1.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,6.4"><Span><Run>High Impact BES Cyber Systems </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Medium Impact BES Cyber Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,1.47,0"><Span><Run>One or more processes to identify, classify, and respond to Cyber Security Incidents. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>but is not limited to, dated documentation of Cyber Security Incident response plan(s) that include the process to identify, classify, and respond to Cyber Security Incidents. </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>1.2</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,6.4"><Span><Run>High Impact BES Cyber Systems </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Medium Impact BES Cyber Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0.93,0"><Span><Run>One or more processes to determine if an identified Cyber Security Incident is a Reportable Cyber Security Incident and notify the Electricity </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Sector Information Sharing and Analysis Center (ES-ISAC), unless prohibited by law.  Initial notification to the ES-ISAC, which may be only a preliminary notice, shall not exceed one hour from the determination of a Reportable Cyber Security Incident. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,11.47,5.33,0.27" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, dated documentation of Cyber Security Incident response plan(s) that provide guidance or thresholds for determining which Cyber Security Incidents are also Reportable Cyber Security Incidents and documentation of initial notices to the Electricity Sector Information Sharing and Analysis Center (ES-ISAC).  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Table CellSpacing="0" Margin="0,0,0,0"><Table