ypography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0.13,10.67"><Run FontFamily="Georgia" FontSize="16">M2. Evidence must include, but is not limited to, documentation that collectively demonstrates implementation of each of the applicable requirement parts in CIP-009-6 Table R2-- Recovery Plan Implementation and Testing.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="55.13" /><TableColumn Width="269.6" /><TableColumn Width="269.6" /><TableColumn Width="269.6" /></Table.Columns><TableRowGroup><TableRow><TableCell Padding="7.13,7.47,6.33,0" BorderThickness="1,1,0,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph></TableCell><TableCell ColumnSpan="3" Padding="7.13,7.47,6.33,0" BorderThickness="0,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="157.33,0,0,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-009-6 Table R2-- Recovery Plan Implementation and Testing </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,6.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.93,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,6.33,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.73,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">