<Section xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xml:space="preserve" TextAlignment="Left" LineHeight="Auto" IsHyphenationEnabled="False" xml:lang="en-us" FlowDirection="LeftToRight" NumberSubstitution.CultureSource="Text" NumberSubstitution.Substitution="AsCulture" FontFamily="Segoe UI" FontStyle="Normal" FontWeight="Normal" FontStretch="Normal" FontSize="12" Foreground="#FF000000" Typography.StandardLigatures="True" Typography.ContextualLigatures="True" Typography.DiscretionaryLigatures="False" Typography.HistoricalLigatures="False" Typography.AnnotationAlternates="0" Typography.ContextualAlternates="True" Typography.HistoricalForms="False" Typography.Kerning="True" Typography.CapitalSpacing="False" Typography.CaseSensitiveForms="False" Typography.StylisticSet1="False" Typography.StylisticSet2="False" Typography.StylisticSet3="False" Typography.StylisticSet4="False" Typography.StylisticSet5="False" Typography.StylisticSet6="False" Typography.StylisticSet7="False" Typography.StylisticSet8="False" Typography.StylisticSet9="False" Typography.StylisticSet10="False" Typography.StylisticSet11="False" Typography.StylisticSet12="False" Typography.StylisticSet13="False" Typography.StylisticSet14="False" Typography.StylisticSet15="False" Typography.StylisticSet16="False" Typography.StylisticSet17="False" Typography.StylisticSet18="False" Typography.StylisticSet19="False" Typography.StylisticSet20="False" Typography.Fraction="Normal" Typography.SlashedZero="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"><Run>M2. Evidence must include the training program that includes each of the applicable requirement parts in CIP-004-6 Table R2-- Cyber Security Training Program and additional evidence to demonstrate implementation of the program(s).</Run></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="85.4" /><TableColumn Width="256.53" /><TableColumn Width="262.2" /><TableColumn Width="259.8" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.27,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R2-- </Run><Span FontFamily="Calibri"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Cyber Security Training Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.27,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.27,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.87"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0.93"><Span><Run>Medium Impact BES Cyber Systems with External Routable Connectivity and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,8.93"><Span><Run>Training content on: </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="2.67,0,0,0.87"><Span><Run>2.1.1.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Cyber security policies; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="2.67,0,0,0.87"><Span><Run>2.1.2.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Physical access controls; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="2.67,0,0,0.87"><Span><Run>2.1.3.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Electronic access controls; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="2.67,0,0,0.87"><Span><Run>2.1.4.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>The visitor control program; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.13,0,0,2.4"><Span><Run>2.1.5.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Handling of BES Cyber System Information and its storage; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.13,0,0,2.4"><Span><Run>2.1.6.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Run>Identification of a Cyber Security Incident and initial notifications in accordance with the entity’s incident response plan; </Run></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.13,0,0,2.47"><Span><Run>2.1.7.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Recovery plans for BES Cyber Systems; </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.13,0,0,2.33"><Span><Run>2.1.8.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Span><Run>Response to Cyber Security Incidents; and </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.13,0,0.13,0"><Span><Run>2.1.9.</Run></Span><Span FontFamily="Arial"><Run> </Run></Span><Run>Cyber security risks associated with a BES Cyber Systems electronic interconnectivity and interoperability with other Cyber Assets, including Transient Cyber Assets, and with Removable Media. </Run></Paragraph></TableCell><TableCell Padding="7.13,7.47,5.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, training material such as power point presentations, instructor notes, student notes, handouts, or other training materials. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"><Span><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="84.73" /><TableColumn Width="257.2" /><TableColumn Width="263" /><TableColumn Width="259" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,5.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R2-- </Run><Span FontFamily="Calibri"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Cyber Security Training Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,4.53,0"><Span FontFamily="