Cell Padding="6.4,7.47,1.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="1.8,0,0,0"><Span><Run>Examples of evidence may include, but are not limited to, dated individual training records. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'Personnel & Training', N'Cyber Security Training Program', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8493, 51, NULL, 27169)
