gin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PACS</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.13,7.47,4.13,3.4" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>Process to confirm identity. </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,4.13,3.4" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of the Responsible </Run></Span></Paragraph><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run>Entity’s process to confirm identity. </Run></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="37.4,0,0.67,10.67"></Paragraph><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,959.6,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="43.07" /><TableColumn Width="274.73" /><TableColumn Width="274.6" /><TableColumn Width="274.6" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.13,7.47,4.07,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,3.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-004-6 Table R3-- </Run><Span FontFamily="Calibri"><Run> </Run></Span><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Personnel Risk Assessment Program </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,4.07,0" BorderThickn