a" FontSize="16">M2. Evidence must include each of the applicable documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table R2-- Security Patch Management and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>A patch management process for tracking, evaluating, and installing cyber security patches for applicable Cyber Assets. The tracking portion shall include the identification of a source or sources that the Responsible Entity tracks for the release of cyber security patches for applicable Cyber Assets that are updateable and for which a patching source exists. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of a patch management process and documentation or lists of sources that are monitored, whether on an individual BES Cyber System or Cyber Asset basis.   </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>At least once every 35 calendar days, evaluate security patches for applicability that have been released since the last evaluation from the source or sources identified in Part 2.1. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, an evaluation conducted by, referenced by, or on behalf of a Responsible Entity of security-related patches released by the documented sources at least once every 35 calendar days.  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>2.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>For applicable patches identified in Part 2.2, within 35 calendar days of the evaluation completion, take one of the following actions: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1.4"><Span><Run>Apply the applicable patches; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2"><Span><Run>Create a dated mitigation plan; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,13.33"><Span><Run>Revise an existing mitigation plan.</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run FontFamily="Calibri">Mitigation plans shall include the Responsible Entitys planned actions to mitigate the vulnerabilities addressed by each security patch and a timeframe to complete these mitigations.  </Run><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>Examples of evidence may include, but are not limited to:  </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>Records of the installation of the patch (e.g., exports from automated patch management tools that provide installation date, verification of BES Cyber</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,2"><Span><Run>System Component software revision, or registry exports that show software has been installed); or</Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>A dated plan showing when</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,0"><Span><Run>and how the vulnerability will be addressed, to include documentation of the actions to be taken by the Responsible Entity to mitigate the vulnerabilities addressed by the security patch and a timeframe for the completion of these mitigations.</Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES  Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>For each mitigation plan created or revised in Part 2.3, implement the plan within the timeframe specified in the plan, unless a revision to the plan or an extension to the timeframe specified in Part 2.3 is approved by the CIP Senior Manager or delegate. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, records of implementation of mitigations. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Security Patch Management', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8541, 10, NULL, 27217)
<Section xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xml:space="preserve" TextAlignment="Left" LineHeight="Auto" IsHyphenationEnabled="False" xml:lang="en-us" FlowDirection="LeftToRight" NumberSubstitution.CultureSource="Text" NumberSubstitution.Substitution="AsCulture" FontFamily="Segoe UI" FontStyle="Normal" FontWeight="Normal" FontStretch="Normal" FontSize="12" Foreground="#FF000000" Typography.StandardLigatures="True" Typography.ContextualLigatures="True" Typography.DiscretionaryLigatures="False" Typography.HistoricalLigatures="False" Typography.AnnotationAlternates="0" Typography.ContextualAlternates="True" Typography.HistoricalForms="False" Typography.Kerning="True" Typography.CapitalSpacing="False" Typography.CaseSensitiveForms="False" Typography.StylisticSet1="False" Typography.StylisticSet2="False" Typography.StylisticSet3="False" Typography.StylisticSet4="False" Typography.StylisticSet5="False" Typography.StylisticSet6="False" Typography.StylisticSet7="False" Typography.StylisticSet8="False" Typography.StylisticSet9="False" Typography.StylisticSet10="False" Typography.StylisticSet11="False" Typography.StylisticSet12="False" Typography.StylisticSet13="False" Typography.StylisticSet14="False" Typography.StylisticSet15="False" Typography.StylisticSet16="False" Typography.StylisticSet17="False" Typography.StylisticSet18="False" Typography.StylisticSet19="False" Typography.StylisticSet20="False" Typography.Fraction="Normal" Typography.SlashedZero="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,0.67"><Run FontFamily="Georgia" FontSize="16">M2. Evidence must include each of the applicable documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table R2-- Security Patch Management and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>A patch management process for tracking, evaluating, and installing cyber security patches for applicable Cyber Assets. The tracking portion shall include the identification of a source or sources that the Responsible Entity tracks for the release of cyber security patches for applicable Cyber Assets that are updateable and for which a patching source exists. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of a patch management process and documentation or lists of sources that are monitored, whether on an individual BES Cyber System or Cyber Asset basis.   </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>At least once every 35 calendar days, evaluate security patches for applicability that have been released since the last evaluation from the source or sources identified in Part 2.1. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, an evaluation conducted by, referenced by, or on behalf of a Responsible Entity of security-related patches released by the documented sources at least once every 35 calendar days.  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>2.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>For applicable patches identified in Part 2.2, within 35 calendar days of the evaluation completion, take one of the following actions: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1.4"><Span><Run>Apply the applicable patches; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2"><Span><Run>Create a dated mitigation plan; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,13.33"><Span><Run>Revise an existing mitigation plan.</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run FontFamily="Calibri">Mitigation plans shall include the Responsible Entitys planned actions to mitigate the vulnerabilities addressed by each security patch and a timeframe to complete these mitigations.  </Run><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>Examples of evidence may include, but are not limited to:  </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>Records of the installation of the patch (e.g., exports from automated patch management tools that provide installation date, verification of BES Cyber</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,2"><Span><Run>System Component software revision, or registry exports that show software has been installed); or</Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>A dated plan showing when</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,0"><Span><Run>and how the vulnerability will be addressed, to include documentation of the actions to be taken by the Responsible Entity to mitigate the vulnerabilities addressed by the security patch and a timeframe for the completion of these mitigations.</Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES  Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>For each mitigation plan created or revised in Part 2.3, implement the plan within the timeframe specified in the plan, unless a revision to the plan or an extension to the timeframe specified in Part 2.3 is approved by the CIP Senior Manager or delegate. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, records of implementation of mitigations. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Security Patch Management', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8542, 10, NULL, 27218)
<Section xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xml:space="preserve" TextAlignment="Left" LineHeight="Auto" IsHyphenationEnabled="False" xml:lang="en-us" FlowDirection="LeftToRight" NumberSubstitution.CultureSource="Text" NumberSubstitution.Substitution="AsCulture" FontFamily="Segoe UI" FontStyle="Normal" FontWeight="Normal" FontStretch="Normal" FontSize="12" Foreground="#FF000000" Typography.StandardLigatures="True" Typography.ContextualLigatures="True" Typography.DiscretionaryLigatures="False" Typography.HistoricalLigatures="False" Typography.AnnotationAlternates="0" Typography.ContextualAlternates="True" Typography.HistoricalForms="False" Typography.Kerning="True" Typography.CapitalSpacing="False" Typography.CaseSensitiveForms="False" Typography.StylisticSet1="False" Typography.StylisticSet2="False" Typography.StylisticSet3="False" Typography.StylisticSet4="False" Typography.StylisticSet5="False" Typography.StylisticSet6="False" Typography.StylisticSet7="False" Typography.StylisticSet8="False" Typography.StylisticSet9="False" Typography.StylisticSet10="False" Typography.StylisticSet11="False" Typography.StylisticSet12="False" Typography.StylisticSet13="False" Typography.StylisticSet14="False" Typography.StylisticSet15="False" Typography.StylisticSet16="False" Typography.StylisticSet17="False" Typography.StylisticSet18="False" Typography.StylisticSet19="False" Typography.StylisticSet20="False" Typography.Fraction="Normal" Typography.SlashedZero="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,0.67"><Run FontFamily="Georgia" FontSize="16">M2. Evidence must include each of the applicable documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table R2-- Security Patch Management and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>A patch management process for tracking, evaluating, and installing cyber security patches for applicable Cyber Assets. The tracking portion shall include the identification of a source or sources that the Responsible Entity tracks for the release of cyber security patches for applicable Cyber Assets that are updateable and for which a patching source exists. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of a patch management process and documentation or lists of sources that are monitored, whether on an individual BES Cyber System or Cyber Asset basis.   </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>At least once every 35 calendar days, evaluate security patches for applicability that have been released since the last evaluation from the source or sources identified in Part 2.1. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, an evaluation conducted by, referenced by, or on behalf of a Responsible Entity of security-related patches released by the documented sources at least once every 35 calendar days.  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>2.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>For applicable patches identified in Part 2.2, within 35 calendar days of the evaluation completion, take one of the following actions: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1.4"><Span><Run>Apply the applicable patches; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2"><Span><Run>Create a dated mitigation plan; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,13.33"><Span><Run>Revise an existing mitigation plan.</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run FontFamily="Calibri">Mitigation plans shall include the Responsible Entitys planned actions to mitigate the vulnerabilities addressed by each security patch and a timeframe to complete these mitigations.  </Run><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>Examples of evidence may include, but are not limited to:  </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>Records of the installation of the patch (e.g., exports from automated patch management tools that provide installation date, verification of BES Cyber</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,2"><Span><Run>System Component software revision, or registry exports that show software has been installed); or</Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>A dated plan showing when</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,0"><Span><Run>and how the vulnerability will be addressed, to include documentation of the actions to be taken by the Responsible Entity to mitigate the vulnerabilities addressed by the security patch and a timeframe for the completion of these mitigations.</Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES  Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>For each mitigation plan created or revised in Part 2.3, implement the plan within the timeframe specified in the plan, unless a revision to the plan or an extension to the timeframe specified in Part 2.3 is approved by the CIP Senior Manager or delegate. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, records of implementation of mitigations. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Security Patch Management', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8543, 10, NULL, 27219)
- Apply the applicable patches; or- Create a dated mitigation plan; or- Revise an existing mitigation plan.Mitigation plans shall include the Responsible Entity’s planned actions to mitigate the vulnerabilities addressed by each security patch and a timeframe to complete these mitigations.', N'<FlowDocument xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"><Section xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xml:space="preserve" TextAlignment="Left" LineHeight="Auto" IsHyphenationEnabled="False" xml:lang="en-us" FlowDirection="LeftToRight" NumberSubstitution.CultureSource="Text" NumberSubstitution.Substitution="AsCulture" FontFamily="Segoe UI" FontStyle="Normal" FontWeight="Normal" FontStretch="Normal" FontSize="12" Foreground="#FF000000" Typography.StandardLigatures="True" Typography.ContextualLigatures="True" Typography.DiscretionaryLigatures="False" Typography.HistoricalLigatures="False" Typography.AnnotationAlternates="0" Typography.ContextualAlternates="True" Typography.HistoricalForms="False" Typography.Kerning="True" Typography.CapitalSpacing="False" Typography.CaseSensitiveForms="False" Typography.StylisticSet1="False" Typography.StylisticSet2="False" Typography.StylisticSet3="False" Typography.StylisticSet4="False" Typography.StylisticSet5="False" Typography.StylisticSet6="False" Typography.StylisticSet7="False" Typography.StylisticSet8="False" Typography.StylisticSet9="False" Typography.StylisticSet10="False" Typography.StylisticSet11="False" Typography.StylisticSet12="False" Typography.StylisticSet13="False" Typography.StylisticSet14="False" Typography.StylisticSet15="False" Typography.StylisticSet16="False" Typography.StylisticSet17="False" Typography.StylisticSet18="False" Typography.StylisticSet19="False" Typography.StylisticSet20="False" Typography.Fraction="Normal" Typography.SlashedZero="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,0.67"><Run FontFamily="Georgia" FontSize="16">M2. Evidence must include each of the applicable documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table R2-- Security Patch Management and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>A patch management process for tracking, evaluating, and installing cyber security patches for applicable Cyber Assets. The tracking portion shall include the identification of a source or sources that the Responsible Entity tracks for the release of cyber security patches for applicable Cyber Assets that are updateable and for which a patching source exists. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of a patch management process and documentation or lists of sources that are monitored, whether on an individual BES Cyber System or Cyber Asset basis.   </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>At least once every 35 calendar days, evaluate security patches for applicability that have been released since the last evaluation from the source or sources identified in Part 2.1. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, an evaluation conducted by, referenced by, or on behalf of a Responsible Entity of security-related patches released by the documented sources at least once every 35 calendar days.  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>2.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>For applicable patches identified in Part 2.2, within 35 calendar days of the evaluation completion, take one of the following actions: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1.4"><Span><Run>Apply the applicable patches; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2"><Span><Run>Create a dated mitigation plan; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,13.33"><Span><Run>Revise an existing mitigation plan.</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run FontFamily="Calibri">Mitigation plans shall include the Responsible Entitys planned actions to mitigate the vulnerabilities addressed by each security patch and a timeframe to complete these mitigations.  </Run><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>Examples of evidence may include, but are not limited to:  </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>Records of the installation of the patch (e.g., exports from automated patch management tools that provide installation date, verification of BES Cyber</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,2"><Span><Run>System Component software revision, or registry exports that show software has been installed); or</Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>A dated plan showing when</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,0"><Span><Run>and how the vulnerability will be addressed, to include documentation of the actions to be taken by the Responsible Entity to mitigate the vulnerabilities addressed by the security patch and a timeframe for the completion of these mitigations.</Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES  Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>For each mitigation plan created or revised in Part 2.3, implement the plan within the timeframe specified in the plan, unless a revision to the plan or an extension to the timeframe specified in Part 2.3 is approved by the CIP Senior Manager or delegate. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, records of implementation of mitigations. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Security Patch Management', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8544, 10, NULL, 27220)
<Section xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xml:space="preserve" TextAlignment="Left" LineHeight="Auto" IsHyphenationEnabled="False" xml:lang="en-us" FlowDirection="LeftToRight" NumberSubstitution.CultureSource="Text" NumberSubstitution.Substitution="AsCulture" FontFamily="Segoe UI" FontStyle="Normal" FontWeight="Normal" FontStretch="Normal" FontSize="12" Foreground="#FF000000" Typography.StandardLigatures="True" Typography.ContextualLigatures="True" Typography.DiscretionaryLigatures="False" Typography.HistoricalLigatures="False" Typography.AnnotationAlternates="0" Typography.ContextualAlternates="True" Typography.HistoricalForms="False" Typography.Kerning="True" Typography.CapitalSpacing="False" Typography.CaseSensitiveForms="False" Typography.StylisticSet1="False" Typography.StylisticSet2="False" Typography.StylisticSet3="False" Typography.StylisticSet4="False" Typography.StylisticSet5="False" Typography.StylisticSet6="False" Typography.StylisticSet7="False" Typography.StylisticSet8="False" Typography.StylisticSet9="False" Typography.StylisticSet10="False" Typography.StylisticSet11="False" Typography.StylisticSet12="False" Typography.StylisticSet13="False" Typography.StylisticSet14="False" Typography.StylisticSet15="False" Typography.StylisticSet16="False" Typography.StylisticSet17="False" Typography.StylisticSet18="False" Typography.StylisticSet19="False" Typography.StylisticSet20="False" Typography.Fraction="Normal" Typography.SlashedZero="False" Typography.MathematicalGreek="False" Typography.EastAsianExpertForms="False" Typography.Variants="Normal" Typography.Capitals="Normal" Typography.NumeralStyle="Normal" Typography.NumeralAlignment="Normal" Typography.EastAsianWidths="Normal" Typography.EastAsianLanguage="Normal" Typography.StandardSwashes="0" Typography.ContextualSwashes="0" Typography.StylisticAlternates="0"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="62.4,0,0,0.67"><Run FontFamily="Georgia" FontSize="16">M2. Evidence must include each of the applicable documented processes that collectively include each of the applicable requirement parts in CIP-007-6 Table R2-- Security Patch Management and additional evidence to demonstrate implementation as described in the Measures column of the table.</Run><Span FontFamily="Georgia" FontSize="16"><LineBreak /></Span></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.6,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.47,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.1 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.33"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>A patch management process for tracking, evaluating, and installing cyber security patches for applicable Cyber Assets. The tracking portion shall include the identification of a source or sources that the Responsible Entity tracks for the release of cyber security patches for applicable Cyber Assets that are updateable and for which a patching source exists. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.13,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, documentation of a patch management process and documentation or lists of sources that are monitored, whether on an individual BES Cyber System or Cyber Asset basis.   </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.33,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.4,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,1.2,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>At least once every 35 calendar days, evaluate security patches for applicability that have been released since the last evaluation from the source or sources identified in Part 2.1. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,6.4,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, an evaluation conducted by, referenced by, or on behalf of a Responsible Entity of security-related patches released by the documented sources at least once every 35 calendar days.  </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0.07,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,0"><Span FontFamily="Calibri"><Run>2.3</Run></Span><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>For applicable patches identified in Part 2.2, within 35 calendar days of the evaluation completion, take one of the following actions: </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,1.4"><Span><Run>Apply the applicable patches; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2"><Span><Run>Create a dated mitigation plan; or</Run></Span></Paragraph></ListItem><ListItem Margin="35.73,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,13.33"><Span><Run>Revise an existing mitigation plan.</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Run FontFamily="Calibri">Mitigation plans shall include the Responsible Entitys planned actions to mitigate the vulnerabilities addressed by each security patch and a timeframe to complete these mitigations.  </Run><Span FontFamily="Calibri" FontWeight="Bold"><Run> </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,9.87"><Span><Run>Examples of evidence may include, but are not limited to:  </Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>Records of the installation of the patch (e.g., exports from automated patch management tools that provide installation date, verification of BES Cyber</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,2"><Span><Run>System Component software revision, or registry exports that show software has been installed); or</Run></Span></Paragraph><List MarkerStyle="Disc" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,3.47,0"><Span><Run>A dated plan showing when</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="48.07,0,0,0"><Span><Run>and how the vulnerability will be addressed, to include documentation of the actions to be taken by the Responsible Entity to mitigate the vulnerabilities addressed by the security patch and a timeframe for the completion of these mitigations.</Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,954.67,0"></Paragraph><Table CellSpacing="0" Margin="0,0,0,0"><Table.Columns><TableColumn Width="72.13" /><TableColumn Width="262.53" /><TableColumn Width="263.73" /><TableColumn Width="265.53" /></Table.Columns><TableRowGroup><TableRow><TableCell ColumnSpan="4" Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF204C81"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Run FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF">CIP-007-6 Table R2-- Security Patch Management </Run></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.8,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,2.67,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>2.4 </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,37"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>Medium Impact BES  Cyber Systems and their associated: </Run></Span></Paragraph><List MarkerStyle="Decimal" Margin="0,0,0,0" Padding="0,0,0,0"><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>EACMS;</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,2.47"><Span><Run>PACS; and</Run></Span></Paragraph></ListItem><ListItem Margin="48.07,0,0,0"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>PCA</Run></Span></Paragraph></ListItem></List></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>For each mitigation plan created or revised in Part 2.3, implement the plan within the timeframe specified in the plan, unless a revision to the plan or an extension to the timeframe specified in Part 2.3 is approved by the CIP Senior Manager or delegate. </Run></Span></Paragraph></TableCell><TableCell Padding="7.6,7.47,4.93,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,0"><Span><Run>An example of evidence may include, but is not limited to, records of implementation of mitigations. </Run></Span></Paragraph></TableCell></TableRow></TableRowGroup></Table><Paragraph FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0,0,0,10.67"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph><Paragraph FontFamily="Georgia" FontSize="16" Margin="0,0,0,0"></Paragraph></Section></FlowDocument>', N'System Security Management', N'Security Patch Management', 0, NULL, N'SET.20231121.102310', NULL, NULL, 8545, 10, NULL, 27221)
