old" Foreground="#FFFFFFFF"><Run>Malicious Code Prevention </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.4,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Part </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.6,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Applicable Systems </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.47,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Requirements </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000" Background="#FF5D85A9"><Paragraph TextAlignment="Center" FontFamily="Times New Roman" FontSize="14.666666666666666" Margin="0.53,0,0,0"><Span FontFamily="Calibri" FontWeight="Bold" Foreground="#FFFFFFFF"><Run>Measures </Run></Span></Paragraph></TableCell></TableRow><TableRow><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0,0,0,0"><Span><Run>3.2 </Run></Span></Paragraph></TableCell><TableCell Padding="7.13,7.47,7.67,0" BorderThickness="1,1,1,1" BorderBrush="#FF000000"><Paragraph FontFamily="Calibri" FontSize="14.666666666666666" Margin="0.07,0,0,1"><Span><Run>High Impact BES Cyber Systems and their associated: </Run></Span></Paragraph><List